<?php
class MigrationCommand {public static $command='migration';public static $description='Manage database migrations (CLI only)';public static $arguments=['[action]'=>'run, status, create-migration, rollback, rollback-all, refresh, seed','[name]'=>'Snake_case migration name'];public function handle($action=null,array $flags=[],$name=null){$m=['run'=>'migrate','status'=>'status','create-migration'=>'create-migration','rollback'=>'rollback','rollback-all'=>'rollback-all','refresh'=>'refresh','seed'=>'lab6-seed'];$action=$action??'run';if(!isset($m[$action])){echo danger('Unknown migration action.');exit(1);}if($action==='create-migration'&&(!$name||!preg_match('/^[a-z][a-z0-9_]*$/D',$name))){echo danger('Provide a snake_case migration name.');exit(1);}$route=$m[$action].($action==='create-migration'?'/'.$name:'');passthru(escapeshellarg(PHP_BINARY).' '.escapeshellarg(PUBLIC_DIR.'index.php').' '.escapeshellarg($route),$code);exit($code);}}
